import { headers } from 'next/headers';

interface UserPreferences {
  theme: string;
  language: string;
  notifications: {
    email: boolean;
    push: boolean;
    sms: boolean;
  };
  timezone: string;
  lastUpdated: string;
}

async function getUserPreferences(): Promise<UserPreferences> {
  const headersList = await headers();
  const host = headersList.get('host') || 'localhost:3000';
  const protocol = process.env.NODE_ENV === 'production' ? 'https' : 'http';

  const res = await fetch(`${protocol}://${host}/api/user/preferences`, {
    cache: 'no-store',
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  return res.json();
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <div>
        <h3>Your Preferences</h3>
        <ul>
          <li>Theme: {preferences.theme}</li>
          <li>Language: {preferences.language}</li>
          <li>Timezone: {preferences.timezone}</li>
        </ul>
        <h3>Notification Settings</h3>
        <ul>
          <li>Email: {preferences.notifications.email ? 'Enabled' : 'Disabled'}</li>
          <li>Push: {preferences.notifications.push ? 'Enabled' : 'Disabled'}</li>
          <li>SMS: {preferences.notifications.sms ? 'Enabled' : 'Disabled'}</li>
        </ul>
        <p>
          <small>Last updated: {preferences.lastUpdated}</small>
        </p>
      </div>
    </div>
  );
}

